 en:{fan:'For the fan',beginner:'New to football',math:'Show the math',analyst:'Tactical',player:'Player focus',waiting:'Watch the build-up',revised:'The evidence changed',goal:'Brooks finishes. Harbor score.',saved:'Berg saves. The score stays level.',passes:'completed passes',goalCount:'goals',focus:'Your player',review:'Evidence review',retain:'KEEP',qualify:'QUALIFY',withdraw:'WITHDRAW',claim:'The run caused the defender to follow.',check:'The movements coincide. Tracking alone cannot prove that one caused the other.',changed:'Corrected tracking keeps Laurent in place. Withdraw the movement claim; retain the passes and shot result.',pending:'Wait for the evidence before asserting a movement claim.',recap:'Sequence recap',partial:'Story so far',synthetic:'Calculated from synthetic coordinates',undefined:'No pass attempts yet',at:'Evidence through',speed:'average pass speed',displacement:'straight-line displacement'},
