export function matchStory(input){
 const s=SCENARIOS.find(s=>s.id===input.scenario)||SCENARIOS[0],language=WORDS[input.language]?input.language:'en',w=WORDS[language],b=sequenceBrief(s,input.time,{...input,language}),m=b.state.metrics,mode=WORDS.en[input.mode]?input.mode:'fan';
 const cards=Object.fromEntries(b.cards.map(c=>[c.id,c])),last=b.state.seen.at(-1),resolved=last?.type==='shot',ready=b.cutoff>={wide:16,press:10,counter:12}[s.id],revised=b.revision===2&&ready;
 const title=revised?w.revised:resolved?(last.outcome==='goal'?w.goal:w.saved):ready?({en:s.title,es:s.esTitle,pt:{wide:'A corrida invisível',press:'Pressão com propósito',counter:'Da calma ao caos'}[s.id]}[language]):w.waiting;
 const player=b.player,allPasses=b.state.seen.filter(e=>e.type==='pass'&&(input.team==='neutral'||e.team===(input.team||'harbor'))),completed=allPasses.filter(e=>e.outcome==='complete');
 const stats=`${input.team==='north'?'Northbridge':input.team==='neutral'?'Harbor + Northbridge':'Harbor'}: ${completed.length}/${allPasses.length} ${w.passes}. ${b.score.harbor}–${b.score.north}.`;
 if(input.team==='north'||input.team==='neutral'){const name=input.team==='north'?'Northbridge':'Harbor + Northbridge',pass=completed.at(-1);cards.math.text=allPasses.length?`${name}: ${completed.length} ÷ ${allPasses.length} × 100 = ${(completed.length/allPasses.length*100).toFixed(1)}% · ${w.passes}.`:`${name}: ${w.undefined}.`;cards.math.equation=pass?`${pass.distance.toFixed(1)} m ÷ ${(pass.end-pass.t).toFixed(1)} s × 3.6 = ${pass.speed.toFixed(1)} km/h`:w.undefined;}
 const playerLine=`${player.name} · ${player.displacement.toFixed(1)} m ${w.displacement} · ${player.completed}/${player.passes} ${w.passes}.`;
 const body=mode==='math'?cards.math.text:mode==='beginner'?cards.beginner.text:mode==='player'?playerLine+' '+cards.analyst.text:cards.analyst.text;
 const equation=cards.math.equation,trace=truthStoryPacket(s,b.cutoff,input.corrected,mode,language),records=new Map(datasetRows(s,b.cutoff,{...input,language}).filter(r=>r.id).map(r=>[r.id,r]));for(const r of trace.evidence)if(r.record_type==='tracking')records.set(r.id,r);const evidence=[...records.values()];
 const coverage={id:`${s.id}-window-${b.cutoff.toFixed(1)}`,record_type:'coverage',second:b.cutoff,description:stats};evidence.push(coverage);
 const review={decision:revised?'withdraw':ready?'qualify':'hold',claim:s.id==='wide'?w.claim:cards.analyst.text,reason:revised?w.changed:ready?(s.id==='wide'?w.check:cards.analyst.note):w.pending,evidence_ids:b.evidenceIds.length?b.evidenceIds:[coverage.id]};
 const definitions={en:{pass:'A pass sends the ball to a teammate.',shot:'A shot is an attempt to score a goal.',tackle:'A recovery means winning the ball back.'},es:{pass:'Un pase envía el balón a un compañero.',shot:'Un disparo es un intento de marcar un gol.',tackle:'Una recuperación significa volver a ganar el balón.'},pt:{pass:'Um passe envia a bola a um companheiro.',shot:'Um chute é uma tentativa de marcar um gol.',tackle:'Uma recuperação significa ganhar a bola de volta.'}},guideDefinition=definitions[language][last?.outcome==='intercepted'?'tackle':last?.type||'pass'];
 return {schema:'btr.match-story.v1',match_id:'btr-'+s.id,scenario:s.id,language,mode,focus:player.id,team:input.team||'harbor',cutoff:b.cutoff,clock:b.clock,revision:b.revision,synthetic:true,title,body,stats,equation,playerLine,guideDefinition,review,resolved,complete:b.cutoff>=s.duration,evidence,trace,brief:b,words:w,
  cue:{...productionPacket(s,b.cutoff,{...input,language,mode:mode==='fan'||mode==='player'?'analyst':mode}),audience:{mode,language,focus_player_id:player.id,team:input.team||'harbor'},overlay:{placement:'lower-left',headline:title,body,...(mode==='math'?{equation}: {})},scope:'The same coordinate-rendered film, match session, discussion and evidence review.'}};
}
export function editorialKey(input){return JSON.stringify([input.scenario,Math.floor(input.time*10)/10,!!input.corrected,input.language,input.mode,Number(input.focus),input.team,input.question||'']);}
export function localPanel(story){const w=story.words,c=Object.fromEntries(story.brief.cards.map(c=>[c.id,c])),ids=story.brief.evidenceIds.length?story.brief.evidenceIds:[story.evidence.at(-1).id];return [
 {role:'analyst',summary:c.analyst.text},
 {role:'guide',summary:guideCue(story)},
 {role:'math',summary:c.math.text,engine:'calculated',working:story.equation},
 {role:'reviewer',summary:story.review.reason,decision:story.review.decision,target_claim:story.review.claim,engine:'evidence_rules'},
 {role:'presenter',summary:matchClosing(story)}
 ].map(p=>({engine:'instant_notes',evidence_ids:ids,cutoff:story.cutoff,revision:story.revision,...p}));}
export function matchExport(input,posts=[]){const s=matchStory(input),contributions=posts.filter(p=>p.cutoff<=s.cutoff&&p.revision===s.revision),records=new Map(s.evidence.map(e=>[e.id,e]));for(const t of new Set(contributions.map(p=>p.cutoff)))for(const e of matchStory({...input,time:t}).evidence)if(!records.has(e.id))records.set(e.id,e);return {schema:s.schema,match_id:s.match_id,scenario:s.scenario,synthetic:true,cutoff:s.cutoff,clock:s.clock,revision:s.revision,audience:s.cue.audience,story:{title:s.title,body:s.body,stats:s.stats},cue:s.cue,review:s.review,evidence:[...records.values()],contributions,limits:['Coordinate-rendered synthetic film; no inferred video tracking.','Editorial interpretations do not prove causation.','Pass speed is a straight-line average, not a calibrated peak measurement.']};}
